"""Finite system-wide Flatpak identities; all start Allowed in the product."""
PLATFORM_ID = 'com.puffyslippers.ONPCTestPlatform'
SDK_ID = 'com.puffyslippers.ONPCTestSdk'
BRANCH = 'stable'
ARCH = 'x86_64'
ASSETS = (
    ('A', 'com.puffyslippers.ONPCTestApplication', 'ONPC Flatpak Allowed Fixture'),
    ('H', 'com.puffyslippers.ONPCTestApplication.Hard', 'ONPC Flatpak Hard Fixture'),
    ('S', 'com.puffyslippers.ONPCTestApplication.Soft', 'ONPC Flatpak Soft Fixture'),
)
MANIFEST = 'flatpak-fixtures.json'


def declarations():
    return {f'runtime/{PLATFORM_ID}/{ARCH}/{BRANCH}': 'onpc-test-platform.flatpak',
            **{f'app/{name}/{ARCH}/{BRANCH}': ('onpc-test-application.flatpak' if role == 'A'
                 else 'onpc-test-' + role.lower() + '.flatpak') for role, name, _ in ASSETS}}


def metadata(name):
    if name == PLATFORM_ID:
        return ('# This file is autogenerated by flatpak build-init\n[Runtime]\n'
                f'name={name}\nsdk={SDK_ID}/{ARCH}/{BRANCH}\n')
    assert name in {item[1] for item in ASSETS}
    return ('# This file is autogenerated by flatpak build-init\n[Application]\n'
            f'name={name}\nruntime={PLATFORM_ID}/{ARCH}/{BRANCH}\n'
            f'sdk={SDK_ID}/{ARCH}/{BRANCH}\ncommand=onpc-test-application\n'
            '\n[Context]\nshared=ipc;\nsockets=wayland;fallback-x11;\n'
            '\n[Environment]\nNO_AT_BRIDGE=0\nGTK_A11Y=atspi\nGSK_RENDERER=cairo\n'
            'FONTCONFIG_PATH=/usr/etc/fonts\n')


def desktop_entry(name, title):
    assert (name, title) in {(item[1], item[2]) for item in ASSETS}
    return (f'[Desktop Entry]\nType=Application\nName={title}\nIcon={name}\n'
            'Exec=onpc-test-application\n')
